import java.util.*;

public class NodeBeam {
    public static void main(String[] args) {
        // Exemplo de entrada (pode ser lido de stdin ou variável)
        String input = "{\"nodes\": [\"[\\\"node_0\\\",  0, 0,   1]\", \"[\\\"node_1\\\",  0, 0,    2]\"]]"; 

